<?php $page_title='Wishlist';include 'partials/header.php';require_login();$uid=$_SESSION['user']['id'];$st=$conn->prepare('SELECT p.* FROM wishlists w JOIN products p ON p.id=w.product_id WHERE w.user_id=? ORDER BY w.id DESC');$st->bind_param('i',$uid);$st->execute();$products=$st->get_result();?><section class="section container"><div class="section-head"><div><span class="muted">Favorit</span><h2>Wishlist Saya</h2></div></div><div class="product-grid"><?php if(!$products->num_rows)echo '<p class="muted">Belum ada produk favorit.</p>';while($p=$products->fetch_assoc())include 'partials/product_card.php';?></div></section><?php include 'partials/footer.php';?>
